def encode_shift(s: str):
    """
    Returns encoded string by shifting every character by 5 in the alphabet.
    Only lowercase alphabetic characters are shifted. Other characters remain unchanged.
    """
    encoded = []
    for ch in s:
        if 'a' <= ch <= 'z':  # Check if the character is a lowercase letter
            encoded.append(chr(((ord(ch) - ord("a") + 5) % 26) + ord("a")))
        else:
            encoded.append(ch)  # Keep non-alphabetic characters unchanged
    return "".join(encoded)


def decode_shift(s: str):
    """
    Takes as input string encoded with encode_shift function. Returns decoded string.
    Only lowercase alphabetic characters are shifted. Other characters remain unchanged.
    """
    decoded = []
    for ch in s:
        if 'a' <= ch <= 'z':  # Check if the character is a lowercase letter
            decoded.append(chr(((ord(ch) - ord("a") - 5) % 26) + ord("a")))
        else:
            decoded.append(ch)  # Keep non-alphabetic characters unchanged
    return "".join(decoded)
